+// Sales from the till: each dish sold uses one recipe portion per qty.
+// Sales are kept in `store.data.sales` (created on first import).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket was imported before. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Books sale lines { ticket, soldAt (ISO), dishId, qty, row }. Skips tickets
+ * already imported. All or nothing: throws bad_request / sale_stock naming
+ * the row and changes nothing. Returns { tickets, dishes } imported.
+ */
+export function importSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const left = new Map();
+  const plan = fresh.map((l) => {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    const needs = scaled(getRecipe(store, dish.recipeId), l.qty);
+    for (const n of needs) {
+      const item = getItem(store, n.itemId);
+      const available = left.get(n.itemId) ?? onHand(store, n.itemId);
+      if (available < n.qty - 1e-9)
+        throw new AppError("sale_stock", { row: l.row, item: item.name, available: Math.round(available * 1000) / 1000, unit: item.unit });
+      left.set(n.itemId, available - n.qty);
+    }
+    return { line: l, needs };
+  });
+  store.data.sales ??= [];
+  for (const { line, needs } of plan) {
+    for (const n of needs) consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: line.ticket,
+      soldAt: line.soldAt,
+      dishId: line.dishId,
+      qty: line.qty,
+    });
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.length };
+}
+
+/**
+ * Per item between two days (inclusive): theoretical use from sales, actual
+ * use from every consume movement, and the difference (actual - theoretical).
+ * Only items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (iso) => {
+    const day = iso.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const theo = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    const dish = getDish(store, s.dishId);
+    for (const n of scaled(getRecipe(store, dish.recipeId), s.qty))
+      theo.set(n.itemId, (theo.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  return [...new Set([...theo.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const theoretical = r3(theo.get(itemId) ?? 0);
+      const act = r3(actual.get(itemId) ?? 0);
+      return { itemId, name: getItem(store, itemId).name, theoretical, actual: act, difference: r3(act - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
